    for i in range(8):
        resultat = str(n % 2) + resultat
        n = n // 2
    return resultat

def nb_sauts(graphe, depart, arrivee):
    distance = {depart: 0}
    file = [depart]
    while file:
        s = file.pop(0)
        if s == arrivee:
            return distance[s]
        for v in graphe[s]:
            if v not in distance:
                distance[v] = distance[s] + 1
                file.append(v)

